/bin/bash -c "cd /home/nitro/Desktop/consensus-assurance/baseline/runs/2026-10-17_20-19-30-dragonboat_raft-baseline/work && python3 - <<'EOF'
p='audit/diag-fixes/raftpb/raft_optimized.go'
s=open(p).read()
old='''func (m *Message) entryCount(dAtA []byte) int {
	l := len(dAtA)
	iNdEx := 0
	count := 0
	for iNdEx < l {
		var wire uint64
		for shift := uint(0); ; shift += 7 {
			b := dAtA[iNdEx]
			iNdEx++
			wire |= (uint64(b) & 0x7F) << shift
			if b < 0x80 {
				break
			}
		}
		fieldNum := int32(wire >> 3)
		if fieldNum == 11 {
			var msglen int
			for shift := uint(0); ; shift += 7 {
				b := dAtA[iNdEx]
				iNdEx++
				msglen |= (int(b) & 0x7F) << shift
				if b < 0x80 {
					break
				}
			}
			count++
			postIndex := iNdEx + msglen
			iNdEx = postIndex
		} else {
			return count
		}
	}
	return count
}'''
new='''func (m *Message) entryCount(dAtA []byte) int {
	l := len(dAtA)
	iNdEx := 0
	count := 0
	for iNdEx < l {
		var wire uint64
		for shift := uint(0); ; shift += 7 {
			if shift >= 64 || iNdEx >= l {
				return count
			}
			b := dAtA[iNdEx]
			iNdEx++
			wire |= (uint64(b) & 0x7F) << shift
			if b < 0x80 {
				break
			}
		}
		fieldNum := int32(wire >> 3)
		if fieldNum == 11 {
			var msglen int
			for shift := uint(0); ; shift += 7 {
				if shift >= 64 || iNdEx >= l {
					return count
				}
				b := dAtA[iNdEx]
				iNdEx++
				msglen |= (int(b) & 0x7F) << shift
				if b < 0x80 {
					break
				}
			}
			if msglen < 0 {
				return count
			}
			postIndex := iNdEx + msglen
			if postIndex > l {
				return count
			}
			count++
			iNdEx = postIndex
		} else {
			return count
		}
	}
	return count
}'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
print('patched entryCount')
EOF
